import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import BackButton from "../components/BackButton";
import Icon from "../components/Icon";
import StandardButton from "../components/StandardButton";
import ActionButton from "../components/ActionButton";
import "../styles/pages/LocationManagement.css";

const LocationManagement = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [locations, setLocations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [showAddModal, setShowAddModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [selectedLocation, setSelectedLocation] = useState(null);
  const [expandedLocations, setExpandedLocations] = useState(new Set());
  
  const [formData, setFormData] = useState({
    name: "",
    code: "",
    type: "location",
    parent: null,
    description: "",
  });

  useEffect(() => {
    fetchLocations();
  }, []);

  const fetchLocations = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem("token");
      const config = {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      };

      const res = await axios.get(
        "https://loto-backend-643788243736.europe-west1.run.app/api/locations",
        config
      );

      if (res.data.success) {
        setLocations(res.data.hierarchy || []);
      }
    } catch (err) {
      setError(err.response?.data?.message || "Failed to fetch locations");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");

    try {
      const token = localStorage.getItem("token");
      const config = {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      };

      if (showEditModal && selectedLocation) {
        // Update existing location
        await axios.put(
          `https://loto-backend-643788243736.europe-west1.run.app/api/locations/${selectedLocation._id}`,
          formData,
          config
        );
        setSuccess("Location updated successfully");
      } else {
        // Create new location
        await axios.post(
          "https://loto-backend-643788243736.europe-west1.run.app/api/locations",
          formData,
          config
        );
        setSuccess("Location created successfully");
      }

      setShowAddModal(false);
      setShowEditModal(false);
      resetForm();
      fetchLocations();
    } catch (err) {
      setError(err.response?.data?.message || "Operation failed");
    }
  };

  const handleDelete = async () => {
    if (!selectedLocation) return;

    try {
      const token = localStorage.getItem("token");
      const config = {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      };

      await axios.delete(
        `https://loto-backend-643788243736.europe-west1.run.app/api/locations/${selectedLocation._id}`,
        config
      );

      setSuccess("Location deleted successfully");
      setShowDeleteConfirm(false);
      setSelectedLocation(null);
      fetchLocations();
    } catch (err) {
      setError(err.response?.data?.message || "Failed to delete location");
      setShowDeleteConfirm(false);
    }
  };

  const openAddModal = (parentLocation = null) => {
    resetForm();
    if (parentLocation) {
      setFormData((prev) => ({
        ...prev,
        parent: parentLocation._id,
        type: getChildType(parentLocation.type),
      }));
    }
    setShowAddModal(true);
  };

  const openEditModal = (location) => {
    setSelectedLocation(location);
    setFormData({
      name: location.name,
      code: location.code || "",
      type: location.type,
      parent: location.parent || null,
      description: location.description || "",
    });
    setShowEditModal(true);
  };

  const openDeleteConfirm = (location) => {
    setSelectedLocation(location);
    setShowDeleteConfirm(true);
  };

  const resetForm = () => {
    setFormData({
      name: "",
      code: "",
      type: "location",
      parent: null,
      description: "",
    });
    setSelectedLocation(null);
  };

  const getChildType = (parentType) => {
    const typeMap = {
      location: "line",
      line: "machine",
    };
    return typeMap[parentType] || "machine";
  };

  const toggleExpand = (locationId) => {
    setExpandedLocations((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(locationId)) {
        newSet.delete(locationId);
      } else {
        newSet.add(locationId);
      }
      return newSet;
    });
  };

  const renderLocationTree = (locationList, level = 0) => {
    return locationList.map((location) => {
      const hasChildren = location.children && location.children.length > 0;
      const isExpanded = expandedLocations.has(location._id);

      return (
        <div key={location._id} className="location-item" style={{ marginLeft: `${level * 20}px` }}>
          <div className="location-header">
            <div className="location-info">
              {hasChildren && (
                <button
                  className="expand-button"
                  onClick={() => toggleExpand(location._id)}
                >
                  <Icon name={isExpanded ? "chevron-down" : "chevron-right"} size="sm" />
                </button>
              )}
              {!hasChildren && <span className="spacer" />}
              
              <div className="location-details">
                <span className="location-name">{location.name}</span>
                <span className={`location-type type-${location.type}`}>
                  {location.type}
                </span>
              </div>
            </div>

            <div className="location-actions">
              {location.type !== "machine" && (
                <ActionButton
                  onClick={() => openAddModal(location)}
                  variant="secondary"
                  icon="plus"
                  size="sm"
                  title={`Add child ${getChildType(location.type)}`}
                />
              )}
              <ActionButton
                onClick={() => openEditModal(location)}
                variant="secondary"
                icon="edit"
                size="sm"
                title="Edit"
              />
              <ActionButton
                onClick={() => openDeleteConfirm(location)}
                variant="danger"
                icon="trash"
                size="sm"
                title="Delete"
              />
            </div>
          </div>

          {hasChildren && isExpanded && (
            <div className="location-children">
              {renderLocationTree(location.children, level + 1)}
            </div>
          )}
        </div>
      );
    });
  };

  if (loading) {
    return (
      <div className="location-management-page">
        <div className="loading-container">
          <Icon name="loader" size="lg" className="spinner" />
          <p>Loading locations...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="location-management-page">
      <BackButton />
      
      <div className="page-header">
        <div className="header-content">
          <Icon name="map-pin" size="lg" />
          <h1>Location Management</h1>
        </div>
        <StandardButton
          onClick={() => openAddModal()}
          variant="primary"
          icon="plus"
        >
          Add Root Location
        </StandardButton>
      </div>

      {error && (
        <div className="alert alert-error">
          <Icon name="alert-circle" size="sm" />
          {error}
        </div>
      )}

      {success && (
        <div className="alert alert-success">
          <Icon name="check-circle" size="sm" />
          {success}
        </div>
      )}

      <div className="locations-container">
        <div className="locations-header">
          <h2>Locations Hierarchy</h2>
          <p className="help-text">
            Manage your locations, lines, and machines. Click the arrows to expand/collapse.
          </p>
        </div>

        {locations.length === 0 ? (
          <div className="empty-state">
            <Icon name="map-pin" size="xl" />
            <p>No locations found. Add your first location to get started.</p>
          </div>
        ) : (
          <div className="locations-tree">
            {renderLocationTree(locations)}
          </div>
        )}
      </div>

      {/* Add/Edit Modal */}
      {(showAddModal || showEditModal) && (
        <div className="modal-overlay" onClick={() => {
          setShowAddModal(false);
          setShowEditModal(false);
          resetForm();
        }}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>
                <Icon name={showEditModal ? "edit" : "plus"} size="md" />
                {showEditModal ? "Edit Location" : "Add New Location"}
              </h2>
              <button
                className="close-button"
                onClick={() => {
                  setShowAddModal(false);
                  setShowEditModal(false);
                  resetForm();
                }}
              >
                <Icon name="x" size="md" />
              </button>
            </div>

            <form onSubmit={handleSubmit}>
              <div className="form-group">
                <label>Name *</label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  required
                  placeholder="e.g., PKG, Line A, Machine DA01"
                />
              </div>

              <div className="form-group">
                <label>Code *</label>
                <input
                  type="text"
                  value={formData.code}
                  onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                  required
                  placeholder="e.g., PKG, A, DA01"
                />
              </div>

              <div className="form-group">
                <label>Type *</label>
                <select
                  value={formData.type}
                  onChange={(e) => setFormData({ ...formData, type: e.target.value })}
                  required
                  disabled={formData.parent !== null}
                >
                  <option value="location">Location</option>
                  <option value="line">Line</option>
                  <option value="machine">Machine</option>
                </select>
                {formData.parent && (
                  <small className="help-text">Type is determined by parent</small>
                )}
              </div>

              <div className="form-group">
                <label>Description</label>
                <textarea
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  rows="3"
                  placeholder="Optional description"
                />
              </div>

              <div className="modal-actions">
                <StandardButton
                  type="button"
                  variant="secondary"
                  onClick={() => {
                    setShowAddModal(false);
                    setShowEditModal(false);
                    resetForm();
                  }}
                >
                  Cancel
                </StandardButton>
                <StandardButton type="submit" variant="primary">
                  {showEditModal ? "Update" : "Create"}
                </StandardButton>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {showDeleteConfirm && (
        <div className="modal-overlay" onClick={() => setShowDeleteConfirm(false)}>
          <div className="modal-content modal-sm" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>
                <Icon name="alert-triangle" size="md" />
                Confirm Delete
              </h2>
            </div>

            <div className="modal-body">
              <p>
                Are you sure you want to delete <strong>{selectedLocation?.name}</strong>?
              </p>
              <p className="warning-text">
                This action cannot be undone. Make sure this location has no children.
              </p>
            </div>

            <div className="modal-actions">
              <StandardButton
                variant="secondary"
                onClick={() => setShowDeleteConfirm(false)}
              >
                Cancel
              </StandardButton>
              <StandardButton
                variant="danger"
                onClick={handleDelete}
              >
                Delete
              </StandardButton>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default LocationManagement;

